// AscendC ForeachMaximumScalarList kernel
// Element-wise max of flat_x and flat_scalar, with fp32 promotion for fp16/bf16.
// Supports: float32, float16, bfloat16, int32

#include "kernel_operator.h"

constexpr int32_t BUFFER_NUM = 2;

// ---------------------------------------------------------------------------
// Inline helpers
// ---------------------------------------------------------------------------

__aicore__ inline uint32_t CeilDivU32(uint32_t a, uint32_t b)
{
    if (b == 0U) { return 0U; }
    return (a + b - 1U) / b;
}

template <typename T>
__aicore__ inline void LoadGmToUb(
    AscendC::LocalTensor<T> &dst,
    const AscendC::GlobalTensor<T> &src,
    uint32_t count)
{
    AscendC::DataCopyExtParams copyParams{1, count * static_cast<uint32_t>(sizeof(T)), 0, 0, 0};
    AscendC::DataCopyPadExtParams<T> padParams{true, 0, 0, static_cast<T>(0)};
    AscendC::DataCopyPad(dst, src, copyParams, padParams);
}

template <typename T>
__aicore__ inline void StoreUbToGm(
    AscendC::GlobalTensor<T> &dst,
    const AscendC::LocalTensor<T> &src,
    uint32_t count)
{
    AscendC::DataCopyExtParams copyParams{1, count * static_cast<uint32_t>(sizeof(T)), 0, 0, 0};
    AscendC::DataCopyPad(dst, src, copyParams);
}

// =========================================================================
// Kernel class for element-wise maximum
// =========================================================================

template <typename dataType>
class ForeachMaximumScalarListKernel {
public:
    __aicore__ inline void Init(
        GM_ADDR flat_x, GM_ADDR flat_scalar, GM_ADDR flat_y,
        int32_t totalNumel, int32_t tileSize,
        int32_t formerNum, int32_t formerLength,
        int32_t tailNum, int32_t tailLength)
    {
        totalNumel_ = totalNumel;
        tileSize_ = tileSize;
        formerNum_ = formerNum;
        formerLength_ = formerLength;
        tailNum_ = tailNum;
        tailLength_ = tailLength;

        uint64_t totalBytes = static_cast<uint64_t>(totalNumel) * sizeof(dataType);

        xGm_.SetGlobalBuffer(reinterpret_cast<__gm__ dataType *>(flat_x), totalBytes);
        sGm_.SetGlobalBuffer(reinterpret_cast<__gm__ dataType *>(flat_scalar), totalBytes);
        yGm_.SetGlobalBuffer(reinterpret_cast<__gm__ dataType *>(flat_y), totalBytes);

        // Double-buffered input/output queues + cast buffers for fp16/bf16
        pipe_.InitBuffer(xQueue_, BUFFER_NUM, static_cast<uint32_t>(tileSize_) * sizeof(dataType));
        pipe_.InitBuffer(sQueue_, BUFFER_NUM, static_cast<uint32_t>(tileSize_) * sizeof(dataType));
        pipe_.InitBuffer(yQueue_, BUFFER_NUM, static_cast<uint32_t>(tileSize_) * sizeof(dataType));
        if constexpr (!std::is_same_v<dataType, int32_t> && !std::is_same_v<dataType, float>) {
            pipe_.InitBuffer(xCastBuf_, static_cast<uint32_t>(tileSize_) * sizeof(float));
            pipe_.InitBuffer(sCastBuf_, static_cast<uint32_t>(tileSize_) * sizeof(float));
            pipe_.InitBuffer(yCastBuf_, static_cast<uint32_t>(tileSize_) * sizeof(float));
        }
    }

    __aicore__ inline void Process()
    {
        // Compute block index and determine which tiles this core handles
        int32_t blockIdx = AscendC::GetBlockIdx();
        int32_t curTileLen;

        if (blockIdx < formerNum_) {
            // Full-size tiles on "former" cores
            int32_t startTile = blockIdx * formerLength_;
            int32_t endTile = startTile + formerLength_;
            for (int32_t t = startTile; t < endTile; ++t) {
                curTileLen = (t == totalTiles_ - 1 && tailLength_ > 0) ? tailLength_ : tileSize_;
                ProcessTile(t, curTileLen);
            }
        } else if (blockIdx == formerNum_ && tailNum_ > 0) {
            // Tail tile on the last core
            ProcessTile(totalTiles_ - 1, tailLength_);
        }
    }

private:
    __aicore__ inline void CopyIn(int32_t tileIdx, int32_t curLen)
    {
        uint64_t offset = static_cast<uint64_t>(tileIdx) * tileSize_;

        xLocal_ = xQueue_.AllocTensor<dataType>();
        LoadGmToUb(xLocal_, xGm_[offset], static_cast<uint32_t>(curLen));
        xQueue_.EnQue(xLocal_);

        sLocal_ = sQueue_.AllocTensor<dataType>();
        LoadGmToUb(sLocal_, sGm_[offset], static_cast<uint32_t>(curLen));
        sQueue_.EnQue(sLocal_);
    }

    __aicore__ inline void Compute(int32_t curLen)
    {
        yLocal_ = yQueue_.AllocTensor<dataType>();

        xLocal_ = xQueue_.DeQue<dataType>();
        sLocal_ = sQueue_.DeQue<dataType>();

        if constexpr (std::is_same_v<dataType, int32_t> || std::is_same_v<dataType, float>) {
            // Float32 or Int32: direct element-wise max
            AscendC::Max(yLocal_, xLocal_, sLocal_, curLen);
        } else {
            // FP16 or BF16: promote to FP32, compute max, cast back
            auto xF32 = xCastBuf_.Get<float>();
            auto sF32 = sCastBuf_.Get<float>();
            auto yF32 = yCastBuf_.Get<float>();

            AscendC::Cast(xF32, xLocal_, AscendC::RoundMode::CAST_NONE, curLen);
            AscendC::Cast(sF32, sLocal_, AscendC::RoundMode::CAST_NONE, curLen);
            AscendC::PipeBarrier<PIPE_V>();

            AscendC::Max(yF32, xF32, sF32, curLen);

            AscendC::Cast(yLocal_, yF32,
                std::is_same_v<dataType, bfloat16_t> ? AscendC::RoundMode::CAST_NONE : AscendC::RoundMode::CAST_NONE,
                curLen);
            AscendC::PipeBarrier<PIPE_V>();
        }

        yQueue_.EnQue(yLocal_);

        xQueue_.FreeTensor(xLocal_);
        sQueue_.FreeTensor(sLocal_);
    }

    __aicore__ inline void CopyOut(int32_t tileIdx, int32_t curLen)
    {
        uint64_t offset = static_cast<uint64_t>(tileIdx) * tileSize_;

        yLocal_ = yQueue_.DeQue<dataType>();
        StoreUbToGm(yGm_[offset], yLocal_, static_cast<uint32_t>(curLen));
        yQueue_.FreeTensor(yLocal_);
    }

    __aicore__ inline void ProcessTile(int32_t tileIdx, int32_t curLen)
    {
        // Pipeline: CopyIn(1st half) → Compute + CopyIn(2nd half) → Compute + CopyOut
        // For simplicity with small tiles, single tile per iteration
        CopyIn(tileIdx, curLen);
        Compute(curLen);
        CopyOut(tileIdx, curLen);
    }

private:
    int32_t totalNumel_ = 0;
    int32_t tileSize_ = 0;
    int32_t totalTiles_ = 0;
    int32_t formerNum_ = 0;
    int32_t formerLength_ = 0;
    int32_t tailNum_ = 0;
    int32_t tailLength_ = 0;

    AscendC::TPipe pipe_;
    AscendC::GlobalTensor<dataType> xGm_;
    AscendC::GlobalTensor<dataType> sGm_;
    AscendC::GlobalTensor<dataType> yGm_;

    AscendC::TQue<AscendC::TPosition::VECIN, BUFFER_NUM> xQueue_;
    AscendC::TQue<AscendC::TPosition::VECIN, BUFFER_NUM> sQueue_;
    AscendC::TQue<AscendC::TPosition::VECOUT, BUFFER_NUM> yQueue_;

    AscendC::TBuf<AscendC::TPosition::VECCALC> xCastBuf_;
    AscendC::TBuf<AscendC::TPosition::VECCALC> sCastBuf_;
    AscendC::TBuf<AscendC::TPosition::VECCALC> yCastBuf_;

    AscendC::LocalTensor<dataType> xLocal_;
    AscendC::LocalTensor<dataType> sLocal_;
    AscendC::LocalTensor<dataType> yLocal_;
};

// =========================================================================
// Kernel entry point — dtype dispatch
// dtypeFlag: 0=fp32, 1=fp16, 2=bf16, 3=int32
// =========================================================================

extern "C" __global__ __aicore__ void foreach_maximum_scalar_list(
    GM_ADDR flat_x, GM_ADDR flat_scalar, GM_ADDR flat_y,
    int32_t totalNumel, int32_t tileSize,
    int32_t formerNum, int32_t formerLength,
    int32_t tailNum, int32_t tailLength,
    int64_t dtypeFlag)
{
    if (dtypeFlag == 0) {
        ForeachMaximumScalarListKernel<float> kernel;
        kernel.Init(flat_x, flat_scalar, flat_y, totalNumel, tileSize, formerNum, formerLength, tailNum, tailLength);
        kernel.Process();
    } else if (dtypeFlag == 1) {
        ForeachMaximumScalarListKernel<half> kernel;
        kernel.Init(flat_x, flat_scalar, flat_y, totalNumel, tileSize, formerNum, formerLength, tailNum, tailLength);
        kernel.Process();
    } else if (dtypeFlag == 2) {
        ForeachMaximumScalarListKernel<bfloat16_t> kernel;
        kernel.Init(flat_x, flat_scalar, flat_y, totalNumel, tileSize, formerNum, formerLength, tailNum, tailLength);
        kernel.Process();
    } else {
        ForeachMaximumScalarListKernel<int32_t> kernel;
        kernel.Init(flat_x, flat_scalar, flat_y, totalNumel, tileSize, formerNum, formerLength, tailNum, tailLength);
        kernel.Process();
    }
}
