// ForeachMaximumScalarList op_host — tiling calculation + EXEC_KERNEL_CMD launch

#include <algorithm>
#include <cstdint>

#include <torch/extension.h>
#include <torch/library.h>

#include "torch_kernel_helper.h"
#include "tiling/platform/platform_ascendc.h"

#include "aclrtlaunch_foreach_maximum_scalar_list.h"

namespace ascend_kernel {

at::Tensor foreach_maximum_scalar_list(
    const at::Tensor &flat_x,
    const at::Tensor &flat_scalar)
{
    // Input validation
    TORCH_CHECK(flat_x.dim() == 1, "flat_x must be 1D");
    TORCH_CHECK(flat_scalar.dim() == 1, "flat_scalar must be 1D");
    TORCH_CHECK(flat_x.numel() == flat_scalar.numel(), "flat_x and flat_scalar must have the same numel");
    TORCH_CHECK(flat_x.scalar_type() == flat_scalar.scalar_type(),
        "flat_x and flat_scalar must have the same dtype");
    TORCH_CHECK(
        flat_x.scalar_type() == at::kFloat || flat_x.scalar_type() == at::kHalf ||
            flat_x.scalar_type() == at::kBFloat16 || flat_x.scalar_type() == at::kInt,
        "flat_x must be float16, bfloat16, float32, or int32");
    TORCH_CHECK(flat_x.is_contiguous(), "flat_x must be contiguous");
    TORCH_CHECK(flat_scalar.is_contiguous(), "flat_scalar must be contiguous");

    int32_t totalNumel = static_cast<int32_t>(flat_x.numel());
    if (totalNumel == 0) {
        return at::empty_like(flat_x);
    }

    // dtype flag: 0=fp32, 1=fp16, 2=bf16, 3=int32
    int64_t dtypeFlag = 0;
    int32_t dtypeSize = 4;
    if (flat_x.scalar_type() == at::kHalf) {
        dtypeFlag = 1;
        dtypeSize = 2;
    } else if (flat_x.scalar_type() == at::kBFloat16) {
        dtypeFlag = 2;
        dtypeSize = 2;
    } else if (flat_x.scalar_type() == at::kInt) {
        dtypeFlag = 3;
        dtypeSize = 4;
    }

    // Get platform info
    auto ascendcPlatform = platform_ascendc::PlatformAscendCManager::GetInstance();
    int64_t coreNum = static_cast<int64_t>(ascendcPlatform->GetCoreNumAiv());
    uint64_t ubSize;
    ascendcPlatform->GetCoreMemSize(platform_ascendc::CoreMemType::UB, ubSize);

    // Tiling: compute tileSize from UB budget
    // For fp16/bf16: 3*BUFFER_NUM queues (2 bytes) + 3 cast buffers (4 bytes)
    //   = BUFFER_NUM * 3 * tile * 2 + 3 * tile * 4 = tile * (6*BUFFER_NUM + 12)
    // For fp32/int32: 3 * BUFFER_NUM queues (4 bytes)
    //   = BUFFER_NUM * 3 * tile * 4 = tile * 12 * BUFFER_NUM
    // BUFFER_NUM = 2
    // fp16: tile * (12 + 12) = tile * 24 → tile = UB / 24
    // fp32: tile * 24 → tile = UB / 24
    // Use safety margin of 0.9, and align to 32
    constexpr int32_t BUFFER_NUM = 2;
    int32_t elementBytes = dtypeSize;
    int32_t castBufBytes = 0;
    if (dtypeFlag == 1 || dtypeFlag == 2) {
        // fp16/bf16: extra cast bufs
        castBufBytes = 3 * 4;  // 3 cast buffers * float(4B)
    }
    int32_t bytesPerElem = BUFFER_NUM * 3 * elementBytes + castBufBytes;
    uint64_t safeUbSize = static_cast<uint64_t>(ubSize * 0.9);
    int32_t maxTileSize = static_cast<int32_t>(safeUbSize / static_cast<uint64_t>(bytesPerElem));
    // Clamp to reasonable range
    if (maxTileSize > 8192) { maxTileSize = 8192; }
    if (maxTileSize < 256) { maxTileSize = 256; }
    // Align to 32 for cache line alignment
    int32_t tileSize = (maxTileSize / 32) * 32;
    if (tileSize < 32) { tileSize = 32; }

    // Compute tile distribution across cores
    int32_t totalTiles = (totalNumel + tileSize - 1) / tileSize;
    int32_t usedCoreNum = static_cast<int32_t>(std::min<int64_t>(coreNum, static_cast<int64_t>(totalTiles)));
    if (usedCoreNum < 1) { usedCoreNum = 1; }

    // Each core processes tiles at stride = usedCoreNum
    // formerNum: cores with `formerLength` tiles, tailNum: cores with `formerLength + 1` tiles
    int32_t tilesPerCore = totalTiles / usedCoreNum;
    int32_t tailTiles = totalTiles % usedCoreNum;
    int32_t formerLength = tilesPerCore;
    int32_t tailNum = tailTiles;
    int32_t formerNum = usedCoreNum - tailNum;

    // For uniform distribution when tailTiles == 0
    int32_t tailLength = tileSize;  // dummy, only used when there is a tail tile
    if (tailNum == 0 && totalTiles > 0) {
        // The last core's last tile may be shorter
        // This is handled in the kernel by comparing with totalNumel
    }

    // Allocate output
    at::Tensor flat_y = at::empty_like(flat_x);

    // All tiling params as left values (required by EXEC_KERNEL_CMD)
    uint32_t blockDim = static_cast<uint32_t>(usedCoreNum);

    EXEC_KERNEL_CMD(foreach_maximum_scalar_list, blockDim,
                    flat_x, flat_scalar, flat_y,
                    totalNumel, tileSize,
                    formerNum, formerLength,
                    tailNum, tailLength,
                    dtypeFlag);

    return flat_y;
}

}  // namespace ascend_kernel
